import React, { useState, useRef, useEffect, useTransition } from "react";
import { useNavigate } from "react-router-dom";
import styled from "styled-components";
import { EventListComponent } from "./Component/MainEventComponent";

import { TfiAngleLeft } from "react-icons/tfi";
import { AiOutlineClose } from "react-icons/ai";
import Footer from "./Component/Footer";
import searchIcon from "./Img/Header/search.svg";
import useDebounce from "./Hook/Debounce";
import dummydata1 from "./Img/Main/dummydata1.svg";
import dummydata2 from "./Img/Main/dummydata2.png";
import dummydata3 from "./Img/Main/dummydata3.jpg";
import dummydata4 from "./Img/Main/dummydata4.jpg";
import dummydata5 from "./Img/Main/dummydata5.gif";
import dummydata6 from "./Img/Main/dummydata6.jpg";
import dummydata7 from "./Img/Main/dummydata7.jpg";
import dummydata8 from "./Img/Main/dummydata8.jpeg";
