import dummydata10 from "./Img/Main/dummydata10.jpg";

const SearchLogCss = styled.div`
  width: 100%;
  display: flex;
  border-radius: 50px;
  align-items: center;
  margin: 0 30px;
  p {
    letter-spacing: -0.02em;
    font-weight: 400;
    font-size: 14px;
    color: #080708;
    width: 95%;
  }

  .fa-x {
    font-size: 16px;
    cursor: pointer;
  }
`;
function SearchLog(props) {
  function deleteLog() {
    for (let i = props.id; true; i++) {
      if (localStorage.getItem("searchlog" + (i + 1)) === null) {
        localStorage.removeItem("searchlog" + i);
        break;
      }
      localStorage.setItem(
        "searchlog" + i,
        localStorage.getItem("searchlog" + (i + 1))
      );
    }
  }

  return (
    <SearchLogCss vh={props.vh}>
      <p
        onClick={() => {
          props.bar.current.value = localStorage.getItem(
            "searchlog" + props.id
          );
          props.search(props.bar.current.value);
          props.setResult(1);
        }}
      >
        {localStorage.getItem("searchlog" + props.id)}
      </p>
      <AiOutlineClose
        onClick={() => {
          deleteLog();
          props.logset();
        }}
        className="fa-solid fa-x"
      />
    </SearchLogCss>
  );
}

const SearchCss = styled.div`
  overflow: hidden;
  background: white;
  width: 100vw;
  max-width: 450px;
  top: 0;

  .link {
    text-decoration: none;
  }

  .searchBar {
    display: flex;
    width: 100%;
    margin: 10px 0;
    align-items: center;

    .fa-angle-left {
      width: 6%;
      margin: 0 3%;
      font-size: 20px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    label {
      margin-right: 20px;
      width: 80%;

      padding: 10px 20px;
      display: flex;
      align-items: center;
      background: #f1f2f4;
      border-radius: 100px;

      input {
        background: none;
        border: 0;
        width: 90%;
        margin-left: 2%;
        height: 22px;
      }
      input:focus {
        outline: none;
      }
    }
  }

  .searchScreen {
    transition: 0.5s;
    .lately {
      ${(props) => (props.result === 0 ? "" : "display:none;")};
      width: 100%;
      .group {
        width: 100%;
        margin-top: 30px;
        display: flex;
        align-items: center;

        .log {
          color: #080708;
          width: 45%;
          margin-left: 5%;
          text-align: left;
          font-size: 14px;
          font-weight: 600;
        }
        .delete {
          display: flex;
          justify-content: center;
          width: 45%;
          text-align: right;
          font-size: 12px;
          font-weight: 400;
        }
      }

      .logContainer {
        overflow-y: auto;
        height: ${(props) => props.vh * 79}px;
        .logList {
          display: flex;
          flex-wrap: wrap;
        }
      }
    }

    .resultContainer {
      ${(props) => (props.result === 1 ? "" : "display:none;")};
      max-width: 450px;
      overflow: hidden;
      .resultMode {
        display: flex;
        p {
          cursor: pointer;
          width: 50%;
          margin: 0;
          padding-bottom: 15px;
          padding-top: 10px;
          display: flex;
          align-items: center;
          justify-content: center;
          background: #ffffff;
          font-weight: 600;
          font-size: 14px;
          transition: 0.3s;
        }
        .event {
          color: ${(props) => (props.mode === 0 ? "#080708" : "#c8c8c8")};
          border-bottom: 2px solid
            ${(props) => (props.mode === 0 ? "#080708" : "#c8c8c8")};
        }
        .hashtag {
          color: ${(props) => (props.mode === 1 ? "#080708" : "#c8c8c8")};
          border-bottom: 2px solid
            ${(props) => (props.mode === 1 ? "#080708" : "#c8c8c8")};
        }
      }
      .result {
        padding: 0 7px;
        height: ${(props) => props.vh * 65}px;
        @media only screen and (min-width: 1024px) {
          .mainContainer {
            height: ${(props) => props.vh * 83}px;
          }
        }

        display: flex;
        transition: 0.3s;
        flex-wrap: wrap;
        justify-content: space-between;
        overflow-y: scroll;
        .nomeet {
          width: 100%;
          display: flex;
          align-items: center;
          justify-content: center;
          height: ${(props) => props.vh * 75}px;
          font-size: 18px;
          font-weight: 400;
          color: #00000088;
        }
      }
    }
  }
`;

function Search() {
  const dummydata = [
    {
      id: 1, // 고유 식별자
      img: dummydata1, // 이미지 URL 또는 null
      charge: 1, // 0=무료,1=유료,2=부분유료
      category: "공연", // “전시회” | “공연” | …
      title: "뮤지컬 〈브로드웨이 42번가〉",
      location: "서울특별시 송파구 잠실동 40-1",
      homepage: "https://tickets.interpark.com/goods/25007451",
      start_date: "2026-01-02T00:00:00",
      end_date: "2026-01-03T00:00:00",
      is_sell: false, // true → 자체판매, false → 외부링크
      event_open_list: [],
      event_close_list: [],
    },
    {
      id: 2,
      img: dummydata2,
      charge: 1,
      category: "전시회",
      title: "아르누보의 꽃: 알폰스 무하 원화전",
      location: "서울특별시 강남구 테헤란로 518 B1, 마이아트뮤지엄",
      homepage: "https://tickets.interpark.com/goods/25001911",
      start_date: "2025-03-20T00:00:00",
      end_date: "2025-07-13T00:00:00",
      is_sell: false,
      event_open_list: [],
      event_close_list: [],
    },
    {
      id: 3,
      img: dummydata3,
      charge: 1,
      category: "공연",
      title: "뮤지컬 〈차미〉",
      location: "서울특별시 종로구 대학로8가길 85, TOM(티오엠) 1관",
      homepage: "https://tickets.interpark.com/goods/25005848",
      start_date: "2025-05-29T00:00:00",
      end_date: "2025-08-24T00:00:00",
      is_sell: false,
      event_open_list: [],
      event_close_list: [],
    },
    {
      id: 4,
      img: dummydata4,
      charge: 1,
      category: "전시회",
      title: "Christian Dior: Designer of Dreams",
      location: "서울특별시 중구 을지로 281, 동대문디자인플라자(DDP)",
      homepage: "https://tickets.interpark.com/goods/25009016",
      start_date: "2025-04-19T00:00:00",
      end_date: "2025-07-13T00:00:00",
      is_sell: false,
      event_open_list: [],
      event_close_list: [],
    },
    {
      id: 5,
      img: dummydata5,
      charge: 1,
      category: "전시회",
      title: "문도 픽사: 픽사, 상상의 세계로",
      location: "서울특별시 성동구 연무장5길 16, 성수문화예술마당",
      homepage: "https://tickets.interpark.com/goods/25004987",
      start_date: "2025-05-05T00:00:00",
      end_date: "2025-07-31T00:00:00",
      is_sell: false,
      event_open_list: [],
      event_close_list: [],
    },
    {
      id: 6,
      img: dummydata6,
      charge: 1,
      category: "공연",
      title: "뮤지컬 〈팬텀〉",
      location: "서울특별시 종로구 세종대로 175, 세종문화회관 대극장",
      homepage: "https://tickets.interpark.com/goods/P0004249",
      start_date: "2025-05-31T00:00:00",
      end_date: "2025-08-11T00:00:00",
      is_sell: false,
      event_open_list: [],
      event_close_list: [],
    },
    {
      id: 7,
      img: dummydata7,
      charge: 1,
      category: "공연",
      title: "뮤지컬 〈멤피스〉",
      location: "서울특별시 중구 퇴계로 387, 충무아트센터 대극장",
      homepage:
        "https://www.shownote.com/Ticket/Performance/Details?performanceId=371",
      start_date: "2025-06-17T00:00:00",
      end_date: "2025-09-21T00:00:00",
      is_sell: false,
      event_open_list: [],
      event_close_list: [],
    },
    {
      id: 8,
      img: dummydata8,
      charge: 1,
      category: "공연",
      title: "뮤지컬 〈민들레 피리〉",
      location: "서울특별시 종로구 대학로12길 21, 예스24스테이지 2관",
      homepage: "https://tickets.interpark.com/goods/25006036",
      start_date: "2025-06-15T00:00:00",
      end_date: "2025-09-07T00:00:00",
      is_sell: false,
      event_open_list: [],
      event_close_list: [],
    },
    {
      id: 9,
      img: dummydata9,
      charge: 0, // 무료
      category: "전시회",
      title: "말하는 머리들",
      location: "서울특별시 중구 덕수궁길 61, 서울시립미술관 서소문본관",
      homepage:
        "https://sema.seoul.go.kr/kr/whatson/exhibition/detail?exNo=1395747",
      start_date: "2025-05-01T00:00:00",
      end_date: "2025-07-06T00:00:00",
      is_sell: false,
      event_open_list: [],
      event_close_list: [],
    },
    {
      id: 10,
      img: dummydata10,
      charge: 0, // 무료
      category: "전시회",
      title: "스토리지 스토리",
      location: "서울특별시 도봉구 마들로13길 68, 서울시립 사진미술관",
      homepage:
        "https://sema.seoul.go.kr/kr/whatson/exhibition/detail?exNo=1410085",
      start_date: "2025-05-29T00:00:00",
      end_date: "2025-10-12T00:00:00",
      is_sell: false,
      event_open_list: [],
      event_close_list: [],
    },
  ];
  const navigate = useNavigate();
  const [result, setResult] = useState(0);
  const [event, setEvent] = useState([]);
  const [hashtag, setHashtag] = useState([]);
  const [size, setSize] = useState(
    window.innerHeight < 600 ? window.screen.availHeight : window.innerHeight
  );
  const [log, setLog] = useState([]);
  const searchBar = useRef(null);
  const [onSearch, setOnSearch] = useState(false);
  const [mode, setMode] = useState(0);
  const searchResult = () => {
    if (searchBar.current.value.replace(/\s/g, "").length === 0) {
      setResult(0);
      searchBar.current.value = "";
    } else {
      for (let i = 0; true; i++) {
        if (localStorage.getItem("searchlog" + i) === searchBar.current.value) {
          deleteLog(i);
        }

        if (localStorage.getItem("searchlog" + i) === null) {
          localStorage.setItem("searchlog" + i, searchBar.current.value);
          break;
        }
      }
      logset();
    }
  };
  const searchEvent = useDebounce(() => {
    if (searchBar.current.value.replace(/\s/g, "").length === 0) {
      setEvent([]);
      setHashtag([]);
      return;
    }

    if (searchBar.current.value !== "") {
      let event_arr = [];
      for (const data of dummydata) {
        if (data.title.includes(searchBar.current.value)) event_arr.push(data);
      }
      setEvent(event_arr);
    } else setEvent([]);
  }, 500);

  function logset() {
    let slog = [];
    for (let i = 0; true; i++) {
      if (localStorage.getItem("searchlog" + i) === null) {
        break;
      }

      slog.push(i);
    }

    setLog(slog.reverse());
  }

  function deleteLogAll() {
    for (let i = 0; true; i++) {
      if (localStorage.getItem("searchlog" + i) === null) {
        break;
      }
      localStorage.removeItem("searchlog" + i);
    }
    setLog([]);
  }

  function deleteLog(id) {
    for (let i = id; true; i++) {
      if (localStorage.getItem("searchlog" + (i + 1)) === null) {
        localStorage.removeItem("searchlog" + i);
        break;
      }

      localStorage.setItem(
        "searchlog" + i,
        localStorage.getItem("searchlog" + (i + 1))
      );
    }
  }

  useEffect(() => {
    window.addEventListener("resize", () => {
      setSize(
        window.innerHeight < 600
          ? window.screen.availHeight
          : window.innerHeight
      );
    });
    logset();
  }, []);

  return (
    <SearchCss result={result} vh={size / 100} mode={mode}>
      <div className="searchBar">
        <div
          className="fa-solid fa-angle-left"
          onClick={() => {
            if (result === 0) navigate(-1);
            else {
              setResult(0);
              searchBar.current.value = "";
            }
          }}
        >
          <TfiAngleLeft />
        </div>
        <label>
          <input
            type="text"
            placeholder="이벤트, 장소를 검색하세요"
            ref={searchBar}
            onFocus={() => {
              setResult(1);
              setOnSearch(true);
            }}
            onBlur={() => {
              searchResult();
              setOnSearch(false);
            }}
            onChange={(e) => {
              searchEvent(e);
            }}
          />
          {!onSearch && <img src={searchIcon} alt="search" />}
          {onSearch && (
            <AiOutlineClose
              onMouseDown={() => {
                searchBar.current.value = "";
              }}
            />
          )}
        </label>
      </div>
      <div className="searchScreen">
        <div className="lately">
          <div className="group">
            <p className="log">최근 검색어</p>
            <p
              className="delete"
              onClick={() => {
                deleteLogAll();
              }}
            >
              모두삭제
            </p>
          </div>

          <div className="logContainer">
            <div className="logList">
              {log.map((e, idx) => {
                return (
                  <SearchLog
                    key={idx}
                    id={e}
                    logset={logset}
                    bar={searchBar}
                    setResult={setResult}
                    search={searchEvent}
                    vh={size / 100}
                  />
                );
              })}
            </div>
          </div>
        </div>

        <div className="resultContainer">
          <div className="resultMode">
            <p
              className="event"
              onClick={() => {
                setMode(0);
              }}
            >
              이벤트
            </p>
            <p
              className="hashtag"
              onClick={() => {
                setMode(1);
              }}
            >
              해시태그
            </p>
          </div>

          {mode === 0 && (
            <div className="result">
              {event.map((e, idx) => {
                return <EventListComponent data={e} key={idx} />;
              })}
              {event.length === 0 && (
                <p className="nomeet">검색결과가 없습니다</p>
              )}
            </div>
          )}
          {mode === 1 && (
            <div className="result">
              {hashtag.map((e, idx) => {
                return <EventListComponent id={e.id} key={idx} />;
              })}
              {hashtag.length === 0 && (
                <p className="nomeet">검색결과가 없습니다</p>
              )}
            </div>
          )}
        </div>
        <div style={{ width: "100%", height: "150px" }}></div>
      </div>

      <Footer mode={2} />
    </SearchCss>
  );
}

export default Search;
