import React, { useEffect, useRef, useState } from "react";
import { styled } from "styled-components";
import { TfiAngleLeft, TfiClose } from "react-icons/tfi";
import { Link, useNavigate } from "react-router-dom";

import locationBlackIcon from "./Img/MainEventComponent/locationBlack.svg";
import dateBlackIcon from "./Img/MainEventComponent/dateBlack.svg";
import minusBtnRed from "./Img/Payment/minusBtnRed.svg";
import minusBtn from "./Img/Payment/minusBtn.svg";
import plusBtnRed from "./Img/Payment/plusBtnRed.svg";
import plusBtn from "./Img/Payment/plusBtn.svg";
import PaymentCalendar from "./Component/PaymentCalendar";
import dummydata1 from "./Img/Main/dummydata1.svg";
import { loadTossPayments, ANONYMOUS } from "@tosspayments/tosspayments-sdk";
import { v4 as uuidv4 } from "uuid";
const PaymentCSS = styled.div`
  margin: 0;
  overflow: auto;
  width: 100vw;
  max-width: 450px;
  height: 82vh;
  @media only screen and (min-width: 1024px) {
    height: 100vh;
  }

  .layout {
    display: flex;
    flex-direction: column;
    padding-bottom: 30vh;
  }
  .top {
    flex: 1;
    display: flex;
    flex-direction: column;
    position: relative;
  }
  .top::before {
    content: "";
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    background-color: black;
    opacity: 0.4;
    z-index: 1;
  }
  .top::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
  }
  .top {
    flex: 1;
    display: flex;
    flex-direction: column;
    background-position: center;
    background-size: cover;
  }
  .bottom {
    flex: 3;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
  }
  .header {
    display: flex;
    align-items: center;
    margin-bottom: auto;
    z-index: 1;
    height: 6vh;
    color: #ffffff;
    padding: 25px;
  }
  .headerBack {
    text-decoration: none;
    text-decoration: none;
    margin-right: auto;
    font-size: 24px;
    color: #ffffff;
  }
  .headerTitle {
    text-decoration: none;
    font-size: 20px;
    font-style: normal;
    font-weight: 600;
  }
  .headerCancel {
    text-decoration: none;
    color: #ffffff;
    text-decoration: none;
    margin-left: auto;
    font-size: 24px;
  }
  .info {
    z-index: 1;
    margin-top: auto;
    padding: 25px;
    .subInfo {
      display: flex;
      align-items: center;
      padding: 5px 0;

      img {
        width: 22px;
        height: 22px;
        margin-right: 8px;
        filter: invert(100%);
      }
      .text {
        color: #ffffff;
        font-size: 14px;
        font-weight: 400;
        margin: 0;
      }
    }
  }
  .selectTitle {
    font-size: 17px;
    font-style: normal;
    font-weight: 500;
    padding-bottom: 10px;
    margin: 16px 20px 0 20px;
    border-bottom: 1.5px solid #e6e6e6;
  }
  .selectDate {
    font-size: 17px;
    font-style: normal;
    font-weight: 500;
    padding-bottom: 10px;
    margin: 16px 20px 0 20px;
    color: #00000088;
  }
  .noBorder {
    border: 0;
  }
  .calender {
    padding: 0 10px;
  }
  .buttonLayout {
    position: fixed;
    width: 100%;
    bottom: -70px;
    max-width: 417px;
    height: 180px;
    padding: 16px;
    background: #fff;
    border-top-left-radius: 12px;
    border-top-right-radius: 12px;
    box-shadow: 0 -2px 6px rgba(0, 0, 0, 0.1);
    transition: bottom 0.3s ease;
  }

  .selectBtn {
    position: absolute;
    display: flex;
    justify-content: center;
    left: 50%;
    width: ${window.innerWidth > 450 ? 410 : window.innerWidth - 40}px;
    transform: translateX(-50%);
    margin-top: auto;
    box-sizing: border-box; /* 패딩/테두리 포함 계산 */
    padding: 14px 0;
    border: 1px solid #981c26;
    font-size: 14px;
    font-weight: 600;
    border-radius: 100px;
    transition: 0.3s;
    background: #ffffff;
    cursor: pointer;
  }
  .selectBtn:hover {
    color: #ffffff;
    background: #981c26;
  }
  .borderLine {
    margin: 0 20px;
    border-bottom: 1.5px solid #e6e6e6;
  }
  .timeLine {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    align-items: center;
    padding: 13px 20px;
  }
  .selectTime {
    padding: 4px 13px 5px 13px;
    display: flex;
    border-radius: 100px;
    font-size: 12px;
    font-weight: 400;
    margin-bottom: 2px;
    align-items: center;
    justify-content: center;
  }
  .selectAmount {
    padding: 17px 0;
    margin: 0 20px;
    border-bottom: 1.5px solid #e6e6e6;
    display: flex;
    align-items: center;
    justify-content: space-between;
    .selectAmountTitle {
      .age {
        padding-bottom: 10px;
        font-size: 15px;
      }
      .price {
        font-weight: 600;
        font-size: 20px;
      }
    }
    .selectAmountBtn {
      display: flex;
      align-items: center;
      gap: 10px;

      .minusBtn,
      .plusBtn {
        display: flex;
        align-items: center;
        justify-content: center;
      }
      .count {
        width: 50px;
        text-align: center;
        font-size: 20px;
        font-weight: 600;
      }
    }
  }
  .total {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 17px 0 24px;
    margin: 0 20px;
    color: #981c26;
    .totalTitle {
      font-weight: 500;
      font-size: 17px;
    }
    .totalPrice {
      font-weight: 600;
      font-size: 20px;
    }
  }
  .reserverInfo {
    margin: 17px 20px 50px 20px;
    display: flex;
    flex-direction: column;
    gap: 10px;
    input {
      padding: 15px 20px;
      border-radius: 10px;
      border: #525252 solid 1px;
      font-size: 14px;
      margin: 5px 0;
      &::placeholder {
        color: #c8c8c8;
      }
      &:focus {
        outline: none;
        border: 1px solid #b03131;
      }
    }
  }

  .payInfo {
    margin: 17px 20px 50px 20px;
    padding: 20px;
    background-color: #ffffff;
    border-radius: 8px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05);
    /* 본문 및 리스트 양쪽정렬처럼 보이기 */
    text-align: justify;
  }

  .payInfo .subTitle {
    position: relative;
    font-size: 16px;
    font-weight: 600;
    color: #333333;
    margin: 16px 0 8px;
    padding-left: 12px;
  }
  .payInfo .subTitle::before {
    content: "";
    position: absolute;
    left: 0;
    top: 50%;
    transform: translateY(-50%);
    width: 4px;
    height: 16px;
    background-color: #981c26;
    border-radius: 2px;
  }

  .payInfo ul.list {
    list-style: none; /* 기본 불릿 제거 */
    margin: 0 0 16px;
    padding: 0 0 0 16px; /* 전체 들여쓰기 */
  }
  .payInfo ul.list > li {
    position: relative;
    margin-bottom: 12px; /* 항목 간 간격 */
    font-size: 12px;
    line-height: 1.5;
    color: #555555;
    text-align: justify; /* 각 항목도 양쪽정렬 */
  }

  /*1단 리스트*/
  .payInfo ul.list > li ul.nested-list {
    list-style: none;
    margin: 8px 0 16px 20px;
    padding: 0;
  }

  /*2단 리스트*/
  .payInfo ul.list > li ul.nested-list > li {
    list-style: disc inside;
    margin: 8px 0;
    font-size: 12px;
    line-height: 1.4;
    color: #333333;
  }

  .indent {
    text-indent: -11px;
    padding-left: 10px;
    margin: 0;
  }
  .paymentMethods {
    margin: 17px 20px 100px 20px;
  }
  [type="radio"] {
    accent-color: #981c26;
    width: 16px;
    height: 16px;
    margin-right: 17px;
  }
  .tosspay {
    padding-bottom: 1.5px;
  }
  .kakaoBtn {
    display: flex;
    align-items: center;
    margin-top: 3px;
  }
  .kakaopay {
    padding-top: 7px;
  }
`;

function Payment() {
  const clientKey = "test_gck_docs_Ovk5rk1EwkEbP0W43n07xlzm";
  const [customerKey, setCustomerKey] = useState(null);
  const day = ["일", "월", "화", "수", "목", "금", "토"];
  //데이터
  const [data, setData] = useState({
    title: "뮤지컬 〈브로드웨이 42번가〉",
    category: "공연",
    location: "서울특별시 송파구 잠실동 40-1",
    place_name: "샤롯데씨어터",
    location_x: 37.5112866236555,
    location_y: 127.097939034042,
    description: `국내 초연 21주년, 브로드웨이 스테디셀러 뮤지컬
    브로드웨이 5,000회 이상 정기공연 기록!
    1996년 국내 초연 이후 21년 동안 써내려간 흥행불패의 신화
    2016년 20주년 공연의 성공적인 피날레에 힘입어
    격이 다른 뮤지컬의 진화판 ‘21년산’으로 되돌아오다.

    경쾌하고 짜릿한 쇼 뮤지컬의 진수, 더욱 완벽해진 무대로 찾아오다!

    20주년 기념공연에서 새롭게 선보인 장면들의 안무, 세트, 조명을 보완해
    압도적인 입체감과 역대 최고 레벨의 탭댄스를 선보인다.
    올 여름 누구나 즐길 수 있는 짜릿한 퍼포먼스와 차원이 다른 고품격 무대가 펼쳐진다.

    BEST CASTING MATCH, 믿고 보는 배우들의 환상적인 조합
    카리스마 넘치는 ‘외강내유’ 형 줄리안 마쉬, 김석훈!
    시크하면서도 반전 있는 ‘외유내강’형 줄리안마쉬, 이종혁!
    21년 만에 뭉친 초연콤비, 최정원, 전수경!
    새롭게 합류한 NEW CAST, 배해선, 오소연!
    환상호흡의 최정예 멤버, 전예지, 에녹, 전재홍!
    새롭고 품격 있는 캐스트로 차원이 다른 21주년 무대를 선보인다.`,
    start_date: "2025-07-10T00:00:00",
    end_date: "2025-09-14T00:00:00",
    open: "오픈 시간",
    close: "휴관 일",
    charge: 1,
    view: 10, //조회수
    wraning: 0, // 신고 횟수
    created_at: "2025-07-10T00:00:00", //작성 일시
    updated_at: "2025-09-14T00:00:00", //마지막 수정 일시
    hashtag_list: ["#신나는", "#탭댄스"], // 해시태그
    event_img_list: [dummydata1],
    event_review_list: [], //이벤트 리뷰 응답형식 참고
    fee: [
      { target: "VIP", price: 130000 },
      { target: "OP석", price: 110000 },
      { target: "R석", price: 110000 },
      { target: "S석", price: 80000 },
      { target: "A선", price: 60000 },
    ],
  });
  const [ticket, setTicket] = useState({});
  const [count, setCount] = useState({});
  const total = useRef(0);
  const customerMobilePhone = useRef();
  const customerEmail = useRef();
  const customerName = useRef();
  //시간
  const [time, setTime] = useState();
  const [selectDate, setSelectDate] = useState();
  const [availableTime, setAvailableTime] = useState({
    월: [],
    화: ["19:30"],
    수: ["14:30", "19:30"],
    목: ["19:30"],
    금: ["19:30"],
    토: ["14:00", " 18:30"],
    일: ["14:00"],
  });

  //결제

  const [amount, setAmount] = useState({
    currency: "KRW",
    value: 0,
  });
  const [ready, setReady] = useState(false);
  const [widgets, setWidgets] = useState(null);

  useEffect(() => {
    const tmp = {};
    const tmp1 = {};
    for (const e of data.fee) {
      tmp[e.target] = 0;
      tmp1[e.target] = 10;
    }
    setCount(tmp);
    setTicket(tmp1);
  }, []);

  useEffect(() => {
    async function fetchPaymentWidgets() {
      // ------  결제위젯 초기화 ------
      const tossPayments = await loadTossPayments(clientKey);
      // 회원 결제

      const widgets = tossPayments.widgets({
        customerKey,
      });
      // 비회원 결제
      // const widgets = tossPayments.widgets({ customerKey: ANONYMOUS });

      setWidgets(widgets);
    }
    if (customerKey === null) {
      setCustomerKey(uuidv4());
    } else {
      fetchPaymentWidgets();
    }
  }, [clientKey, customerKey]);

  useEffect(() => {
    async function renderPaymentWidgets() {
      if (widgets == null) {
        return;
      }
      // ------ 주문의 결제 금액 설정 ------
      await widgets.setAmount(amount);

      await Promise.all([
        // ------  결제 UI 렌더링 ------
        widgets.renderPaymentMethods({
          selector: "#payment-method",
          variantKey: "DEFAULT",
        }),
        // ------  이용약관 UI 렌더링 ------
        widgets.renderAgreement({
          selector: "#agreement",
          variantKey: "AGREEMENT",
        }),
      ]);

      setReady(true);
    }

    renderPaymentWidgets();
  }, [widgets]);

  useEffect(() => {
    if (widgets == null) {
      return;
    }

    widgets.setAmount(amount);
  }, [widgets, amount]);

  const verifyCustomerData = () => {
    if (customerName.current.value === "") {
      alert("이름을 입력해주세요");
      customerName.current.focus();
      return false;
    }
    if (customerMobilePhone.current.value === "") {
      alert("전화번호를 입력해주세요");
      customerMobilePhone.current.focus();
      return false;
    }
    if (customerEmail.current.value === "") {
      alert("이메일을 입력해주세요");
      customerEmail.current.focus();
      return false;
    }
    return true;
  };
  const generateRandomString = () => window.btoa(Math.random()).slice(0, 20);
  async function handleRequestPayment() {
    try {
      if (amount.value <= 0) {
        alert("구매할 티켓을 선택하세요");
        return;
      }

      if (!verifyCustomerData()) return;

      // ------ '결제하기' 버튼 누르면 결제창 띄우기 ------
      // 결제를 요청하기 전에 orderId, amount를 서버에 저장하세요.
      // 결제 과정에서 악의적으로 결제 금액이 바뀌는 것을 확인하는 용도입니다.
      await widgets.requestPayment({
        orderId: generateRandomString(),
        orderName: `${data.title} ${total}장`,
        successUrl: window.location.origin + "/nearby/payment/success",
        failUrl: window.location.origin + "/nearby/payment/fail",
        customerEmail: customerEmail.current.value,
        customerMobilePhone: customerMobilePhone.current.value,
        customerName: customerName.current.value,
      });
    } catch (error) {
      // 에러 처리하기
      console.error(error);
    }
  }

  return (
    <PaymentCSS>
      <div className="layout">
        <div
          className="top"
          style={{ background: `url(${data.event_img_list[0]})` }}
        >
          <div className="header">
            <Link className="headerBack" to="/nearby/event/detail">
              <TfiAngleLeft />
            </Link>
            <p className="headerTitle">{data.title}</p>
            <Link className="headerCancel" to="/nearby/event/detail">
              <TfiClose />
            </Link>
          </div>

          <div className="info">
            <div className="subInfo">
              <img src={dateBlackIcon} alt="date" />
              <p className="text">{data.start_date + " - " + data.end_date}</p>
            </div>
            <div className="subInfo">
              <img src={locationBlackIcon} alt="location" />
              <span className="text">
                {data.location + " " + data.place_name}
              </span>
            </div>
          </div>
        </div>

        <div className="bottom">
          <div className="page1">
            <p className="selectTitle">날짜를 선택해주세요</p>
            <div className="calender">
              <PaymentCalendar
                selectDate={selectDate}
                setSelectDate={setSelectDate}
                minDate={new Date(data.start_date)}
                maxDate={new Date(data.end_date)}
              />
            </div>
            {selectDate !== undefined && (
              <div>
                <p className="borderLine"></p>
                <div className="timeLine">
                  {availableTime[day[selectDate.getDay()]].map(
                    (time, index) => (
                      <span
                        key={index}
                        onClick={() => {
                          setTime(time);
                        }}
                        className="selectTime"
                        style={{
                          background: true ? "#981c26" : "#f2f3f5",
                          color: true ? "#ffffff" : "#080708",
                        }}
                      >
                        {time}
                      </span>
                    )
                  )}
                </div>
              </div>
            )}
          </div>

          <div className="page2">
            <p className="selectTitle">인원/수량을 선택해주세요</p>
            {selectDate !== undefined && (
              <p className="selectDate">
                {selectDate
                  .toISOString()
                  .split("T")[0]
                  .replace("-", ".")
                  .replace("-", ".")}
                &nbsp;
                {time !== undefined && time}
              </p>
            )}
            {data.fee.map((e, idx) => (
              <div className="selectAmount" key={idx}>
                <div className="selectAmountTitle">
                  <div className="age">{e.target}</div>
                  <div className="price">{e.price}원</div>
                </div>
                <div className="selectAmountBtn">
                  <div
                    className="minusBtn"
                    onClick={() => {
                      if (count[e.target] > 0) {
                        const amount_copy = { ...amount };
                        const buf = { ...count };
                        buf[e.target] -= 1;
                        setCount(buf);
                        amount_copy.value = amount_copy.value - e.price;
                        setAmount(amount_copy);
                        total.current -= 1;
                      }
                    }}
                  >
                    <img
                      src={count[e.target] > 0 ? minusBtnRed : minusBtn}
                      alt="minusBtn"
                    />
                  </div>
                  <div className="count">{count[e.target]}</div>
                  <div
                    className="plusBtn"
                    onClick={() => {
                      if (ticket[e.target] > count[e.target]) {
                        const amount_copy = { ...amount };
                        const buf = { ...count };
                        buf[e.target] += 1;
                        setCount(buf);
                        amount_copy.value = amount_copy.value + e.price;
                        setAmount(amount_copy);
                        total.current += 1;
                      }
                    }}
                  >
                    <img
                      src={
                        ticket[e.target] > count[e.target]
                          ? plusBtnRed
                          : plusBtn
                      }
                      alt="plusBtn"
                    />
                  </div>
                </div>
              </div>
            ))}
          </div>

          <div className="Page3">
            <p className="selectTitle noBorder">예매자 정보 입력</p>
            <div className="reserverInfo">
              <input
                type="text"
                placeholder="이름을 입력해주세요"
                ref={customerName}
              />
              <input
                type="tel"
                placeholder="연락처를 입력해주세요 ex) 01012341234"
                pattern="[0-9]{3}[0-9]{4}[0-9]{4}"
                ref={customerMobilePhone}
              />
              <input
                type="text"
                placeholder="이메일 주소를 입력해주세요 ex) nearby@naver.com"
                ref={customerEmail}
              />
            </div>
            <p className="selectTitle">판매 정보</p>
            <div className="payInfo">
              {/* 티켓수령 안내 */}
              <p className="subTitle">티켓수령 안내</p>
              <ul className="list">
                <li>
                  공연 당일 현장 교부처에서 예약번호 및 본인 확인 후 티켓을
                  수령하실 수 있습니다.
                </li>
                <li>
                  상단 예매확인/취소 메뉴에서 예매내역을 프린트하여 가시면
                  편리합니다.
                </li>
              </ul>

              {/* 환불 안내 */}
              <p className="subTitle">환불 안내</p>
              <ul className="list">
                <li>
                  당사의 취소 처리가 완료되고 4-5일 후 카드사의 취소가
                  확인됩니다.
                </li>
                <li>
                  예매 취소 시점과 해당 카드사의 환불 처리기준에 따라 취소금액의
                  환급방법과 환급일은 다소 차이가 있을 수 있으며, 예매 취소 시
                  기존에 결제하였던 내역을 취소하며 최초 결제하셨던 동일카드로
                  취소 시점에 따라 취소수수료를 재승인합니다.
                </li>
              </ul>

              {/* 취소수수료 안내 */}
              <p className="subTitle">취소수수료 안내</p>
              <ul className="list">
                <li>
                  예매 후 7일까지 취소 시에는 취소수수료가 없습니다. 단,
                  취소수수료가 적용되는 기간일 시 관람일 기준 동일한
                  취소수수료가 적용됩니다.
                </li>
                <li>
                  관람일 기준, 아래의 취소수수료가 적용됩니다.
                  <ul className="nested-list">
                    <li>관람일 9일전 - 7일전까지 : 티켓금액의 10%</li>
                    <li>관람일 6일전 - 3일전까지 : 티켓금액의 20%</li>
                    <li>관람일 2일전 - 1일전까지 : 티켓금액의 30%</li>
                  </ul>
                </li>
                <li>
                  상품의 특성에 따라서, 취소수수료 정책이 달라질 수 있습니다.
                </li>
              </ul>
            </div>

            <p className="selectTitle">결제수단</p>
            <div className="wrapper">
              <div className="box_section">
                {/* 결제 UI */}
                <div id="payment-method" />
                {/* 이용약관 UI */}
                <div id="agreement" />
              </div>
            </div>
          </div>
        </div>

        <div className="buttonLayout">
          <div className="total">
            <div className="totalTitle">결제 예정 금액</div>
            <div className="totalPrice">{amount.value}원</div>
          </div>
          <button
            className="selectBtn"
            disabled={!ready}
            onClick={handleRequestPayment}
          >
            결제하기
          </button>
        </div>
      </div>
    </PaymentCSS>
  );
}

export default Payment;
