import React, { useRef } from "react";
import styled from "styled-components";
import useLazyBackground from "./Hook/useLazyBackground";

import img1 from "./Img/Main/dummydata1.svg";
import img2 from "./Img/Main/dummydata2.png";
import img3 from "./Img/Main/dummydata3.jpg";
import img4 from "./Img/Main/dummydata4.jpg";
import img5 from "./Img/Main/dummydata5.gif";
import img6 from "./Img/Main/dummydata6.jpg";
import img7 from "./Img/Main/dummydata7.jpg";
import img8 from "./Img/Main/dummydata8.jpeg";
import img9 from "./Img/Main/dummydata9.jpg";
import img10 from "./Img/Main/dummydata10.jpg";
import img11 from "./Img/Main/dummynotice1.png";
import img12 from "./Img/Main/dummynotice2.jpg";

const Wrapper = styled.div`
  height: 100vh;
  overflow-y: auto;
  padding: 32px;
  box-sizing: border-box;
  background: #f7f7f7;
`;

const Spacer = styled.div`
  height: 600px; /* 상단 여백: 첫 이미지가 안 보이게 */
`;

const Card = styled.div`
  width: 260px;
  height: 360px;
  margin: 0 auto 48px;
  border-radius: 20px;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.08);
  background: #ccc; /* 기본 회색, 훅에서 이미지+투명도 처리 */
`;

/* ---------- 개별 카드 ---------- */
function LazyCard({ url }) {
  const ref = useRef(null);
  useLazyBackground(ref, url);
  return <Card ref={ref} />;
}

/* ---------- 테스트 페이지 ---------- */
export default function LazyLoadTest() {
  const imgs = [
    img1,
    img2,
    img3,
    img4,
    img5,
    img6,
    img7,
    img8,
    img9,
    img10,
    img11,
    img12,
  ];

  return (
    <Wrapper>
      <Spacer /> {/* ① 화면을 내려야 첫 이미지가 보임 */}
      {imgs.map((u, i) => (
        <LazyCard key={i} url={u} />
      ))}
      <Spacer /> {/* ② 마지막 이미지 후 추가 여백 */}
    </Wrapper>
  );
}
