import styled from "styled-components";
import { useEffect, useState } from "react";
import PostComponent from "../../components/postComponent";
import { usePostsStore } from "../../store/postsStore";
import useDebounce from "../../hooks/useDebounce";
import { IoSearchOutline } from "react-icons/io5";
import { useParams } from "react-router-dom";
const TagPostsCss = styled.div`
  width: 100%;
  height: 82vh;
  overflow: auto;
  padding: 20px;
  box-sizing: border-box;
  @media only screen and (min-width: 1024px) {
    height: 100vh;
    padding: 60px;
  }
  .intro {
    font-weight: 500;
    font-style: normal;
    line-height: 1;
    color: #2a2f36;
    font-size: 50px;
  }
  .searchBar {
    display: flex;
    width: 100%;
    margin-bottom: 40px;
    padding: 10px 20px;
    box-sizing: border-box;
    border-radius: 12px;
    align-items: center;
    justify-content: space-between;
    border: 1px solid #000000;
    @media only screen and (min-width: 1024px) {
      padding: 12px 20px;
    }
    input {
      border: 0;
      width: 95%;
      font-size: 16px;
      @media only screen and (min-width: 1024px) {
        font-size: 20px;
      }
    }
    input:focus {
      outline: none;
    }
    .icon {
      font-size: 24px;
    }
  }
  .list {
    padding-bottom: 20px;
  }
`;

function TagPosts() {
  const params = useParams();
  const tags = usePostsStore((state) => state.tags);
  const [result, setResult] = useState(tags[params.tag]);
  const [text, setText] = useState("");
  const debouncedValue = useDebounce(text, 500);
  useEffect(() => {
    if (debouncedValue.length === 0) setResult(tags[params.tag]);
    else {
      const lowCase = debouncedValue.toLowerCase();
      let result_copy = [];
      for (const post of tags[params]) {
        if (post.title.toLowerCase().includes(lowCase)) result_copy.push(post);
      }
      setResult(result_copy);
    }
  }, [debouncedValue]);

  useEffect(() => {});
  return (
    <TagPostsCss>
      <label className="searchBar">
        <input
          type="text"
          onChange={(e) => {
            setText(e.target.value);
          }}
        />
        <IoSearchOutline className="icon" />
      </label>
      <div className="list">
        {result.map((e, idx) => {
          return (
            <PostComponent
              link={`/posts/${idx + 1}`}
              title={e.title}
              src={e.src}
              date={e.date}
              summary={e.summary}
              tags={e.tags}
              key={idx}
            />
          );
        })}
      </div>
    </TagPostsCss>
  );
}

export default TagPosts;
