import React, { useState, useEffect, useRef } from "react";
import styled from "styled-components";
import { Link, useNavigate } from "react-router-dom";
import Footer from "./Component/Footer";

import dateIcon from "./Img/Detail/date.svg";
import locationIcon from "./Img/Detail/location.svg";
import fillstarIcon from "./Img/Detail/fillstar.svg";
import emptystarIcon from "./Img/Detail/emptyStar.svg";
import { TfiAngleLeft } from "react-icons/tfi";
import EventReviewComponent from "./Component/EventReviewComponent";
import dummydata1 from "./Img/Main/dummydata1.svg";
const EventReviewListCss = styled.div`
  width: 100vw;
  height: 82vh;
  @media only screen and (min-width: 1024px) {
    height: 100vh;
  }

  max-width: 450px;
  overflow: auto;
  .header {
    display: flex;
    align-items: center;
    width: 100%;
    .headerTitle {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 80%;
      font-size: 14px;
      font-weight: 600;
    }
  }

  .title {
    font-size: 14px;
    font-weight: 600;
  }
  .container {
    margin: 0 20px;
    padding: 20px 0 10px 0;
    border-bottom: 1px solid #c8c8c8;
    .category {
      font-size: 14px;
      font-weight: 600;
    }
    .star {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 20px 0 8px 0;
    }
    .starRating {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
      font-weight: 600;
      margin-top: 0;
      margin-bottom: 40px;
      .gray {
        color: #c8c8c8;
        margin-right: 3px;
      }
    }
  }
  .eventInfo {
    display: flex;
    align-items: center;
    margin: 10px 0;
    .text {
      margin-left: 8px;
      font-size: 12px;
      font-weight: 400;
    }
  }

  .reviewList {
    margin: 0 20px;
    padding: 20px 0 10px 0;
    max-width: 436px;
    height: 90%;
  }
  .back {
    ${(props) => props.select.id < 0 && !props.confirm && "display:none"};
    position: fixed;
    top: 18vh;
    height: 82vh;
    @media only screen and (min-width: 1024px) {
      top: 0;
      height: 100vh;
    }
    width: 100vw;
    max-width: 450px;
    background: rgba(8, 7, 8, 0.3);
    z-index: 2;
  }
  .popup {
    position: fixed;
    width: 100vw;
    border-radius: 10px 10px 0px 0px;
    max-width: 450px;
    bottom: ${(props) => (props.select.id >= 0 && !props.confirm ? 0 : -300)}px;
    transition: 0.3s;
    z-index: 11;
    background: #fff;
    .text {
      width: ${window.innerWidth > 450 ? 410 : window.innerWidth - 40};
      margin: 0 20px;
      padding: 20px 0;
      font-size: 14px;
      font-weight: 400;
      color: #080708;
      cursor: pointer;
    }
    .border {
      border-bottom: 1px solid #c8c8c888;
    }

    .cancle {
      width: 100%;
      text-align: center;
      font-size: 14px;
      font-weight: 400;
      color: #080708;
    }
    .red {
      color: #981c26;
    }
  }

  .popup1 {
    position: fixed;
    width: 100vw;
    border-radius: 10px 10px 0px 0px;
    max-width: 450px;
    bottom: ${(props) => (props.confirm ? 0 : -300)}px;
    transition: 0.3s;
    z-index: 3;
    background: #fff;
    .text {
      padding: 30px 0;
      width: 100%;
      text-align: center;
      font-size: 14px;
      font-weight: 400;
    }

    .delete {
      border-radius: 100px;
      text-align: center;
      background: #981c26;
      width: 90%;
      margin: 10px 5%;
      color: #fff;
      padding: 15px 0;
    }
    .cancle {
      border-radius: 100px;
      border: 1px solid #981c26;
      text-align: center;
      background: #fff;
      width: 90%;
      margin: 10px 5% 20px 5%;
      color: #981c26;
      padding: 15px 0;
    }
  }
`;
function EventReviewList() {
  const navigate = useNavigate();
  const container = useRef();
  const listRef = useRef();
  const [scroll, setScroll] = useState(4);
  const [review, setReview] = useState([
    {
      id: 1, //포스트 리뷰 번호
      content: "재밌습니다 추천",
      star_rating: 4, //별점
      image: [dummydata1, dummydata1, dummydata1, dummydata1],
      warning: 2, // 신고 횟수
      created_at: "2024-01-01T00:00:00", // 작성 일시
      updated_at: "2024-01-01T00:00:00", //마지막 업데이트 일시
      event_id: 1, // 이벤트 번호
      user: { id: 1, nickname: "사용자 1" }, //작성자 회원번호
    },
    {
      id: 1, //포스트 리뷰 번호
      content: "배우들이 연기를 잘해서 몰입됐어요",
      star_rating: 5, //별점
      image: [dummydata1, dummydata1, dummydata1, dummydata1],
      warning: 2, // 신고 횟수
      created_at: "2024-01-01T00:00:00", // 작성 일시
      updated_at: "2024-01-01T00:00:00", //마지막 업데이트 일시
      event_id: 1, // 이벤트 번호
      user: { id: 2, nickname: "사용자 2" }, //작성자 회원번호
    },
  ]);
  const [starRating, setStarRating] = useState((0).toFixed(1));
  const [event, setEvent] = useState({
    location: "서울특별시 송파구 잠실동 40-1",
    place_name: "샤롯데씨어터",
    category: "공연",
    title: "뮤지컬 〈브로드웨이 42번가〉",
    start_date: dateFromat("2025-07-10T00:00:00"),
    end_date: dateFromat("2025-09-14T00:00:00"),
  });
  const [select, setSelect] = useState({ id: -1, writer: -1 });

  const [confirm, setConfirm] = useState(false);
  const color = {
    전시회: "#1593FF",
    공연: "#F3757C",
    축제: "#EFA116",
    "원데이 클래스": "#981C26",
  };
  function dateFromat(date) {
    return date.split("T")[0].replace("-", ".");
  }
  const deleteEventReview = () => {
    alert("삭제되었습니다");
    window.location.reload();
  };

  const StarComponent = (props) => {
    let buf = [];
    let size = props.size === null ? "14px" : props.size + "px";
    for (let i = 0; i < 5; i++) {
      buf.push(
        <img
          src={i < Math.floor(starRating) ? fillstarIcon : emptystarIcon}
          alt="fillStar"
          key={i}
          style={{ width: size, height: size }}
        />
      );
    }
    return buf;
  };
  useEffect(() => {
    let total = 0;
    for (const e of review) {
      total += e.star_rating;
    }
    setStarRating((total / review.length).toFixed(1));
  }, [review]);
  return (
    <EventReviewListCss
      ref={container}
      select={select}
      confirm={confirm}
      onScroll={(e) => {
        if (e.target.scrollTop + window.innerHeight > e.target.scrollHeight)
          setScroll(scroll + 2);
      }}
    >
      <div className="header">
        <TfiAngleLeft
          style={{ fontSize: "20px", marginLeft: "20px" }}
          onClick={() => {
            navigate("/nearby/event/detail");
          }}
        />
        <p className="headerTitle">관람 후기</p>
      </div>
      <div className="container">
        <span className="category" style={{ color: color[event.category] }}>
          {event.category}
        </span>
        <p className="title">{event.title}</p>
        <div className="eventInfo">
          <img alt="date" src={dateIcon} />
          <span className="text">
            {event.start_date + " - " + event.end_date}
          </span>
        </div>
        <div className="eventInfo">
          <img alt="location" src={locationIcon} />
          <span className="text">
            {event.location + " " + event.place_name}
          </span>
        </div>
      </div>
      <div className="container">
        <span className="title">이벤트 만족도</span>
        <div className="star">
          <StarComponent size={30} />
        </div>
        <p className="starRating">
          <span className="gray">{starRating}</span>
          {" / 5.0"}
        </p>
      </div>
      <div className="reviewList" ref={listRef}>
        <span className="title">전체 관람 후기</span>
        {review.map((e, idx) => {
          if (idx < scroll)
            return (
              <EventReviewComponent
                container={container}
                data={e}
                setSelect={setSelect}
                key={idx}
              />
            );
          else return <></>;
        })}
        <div style={{ height: "120px", width: "100%" }}></div>
      </div>
      <div
        className="back"
        onClick={() => {
          setSelect({ id: -1, writer: -1 });
          setConfirm(false);
        }}
      ></div>

      <div className="popup">
        {select.writer === (Number(sessionStorage.getItem("id")) || -1) && (
          <>
            <Link
              to={
                //해당 부분 수정 필요
                "/d" + event.id + "&mode=edit&id=" + select.id
              }
              style={{ textDecoration: "none" }}
            >
              <p className="text">관람 후기 수정</p>
            </Link>

            <p
              className="text red border"
              onClick={() => {
                setConfirm(true);
              }}
            >
              관람 후기 삭제
            </p>
          </>
        )}
        {select.writer !== (Number(sessionStorage.getItem("id")) || -1) && (
          <Link to={"/nearby/report"} style={{ textDecoration: "none" }}>
            <p className="text red border">신고하기</p>
          </Link>
        )}
        <p
          className="cancle"
          onClick={() => {
            setSelect({ id: -1, writer: -1 });
          }}
        >
          취소
        </p>
      </div>

      <div className="popup1">
        <p className="text">관람 후기를 삭제하시겠어요?</p>
        <p
          className="delete"
          onClick={() => {
            deleteEventReview();
          }}
        >
          관람 후기 삭제
        </p>

        <p
          className="cancle"
          onClick={() => {
            setSelect({ id: -1, writer: -1 });
            setConfirm(false);
          }}
        >
          취소
        </p>
      </div>

      <Footer mode={-1} />
    </EventReviewListCss>
  );
}

export default EventReviewList;
