import { Link } from "react-router-dom";
import styled from "styled-components";

const ProjectComponentCss = styled.div`
  margin: 80px 0;
  .link {
    text-decoration: none;
  }
  .link:visited {
    color: inherit;
  }
  .background {
    background-position: center;
    background-size: cover;
    background-repeat: no-repeat;
    width: 100%;
    height: 50vw;
    @media only screen and (min-width: 1024px) {
      height: 35vw;
    }
    box-sizing: border-box;
  }

  .content {
    flex-direction: column;
    justify-content: center;
    align-items: center;
    width: 100%;
    margin: 0;
    display: none;
    @media only screen and (min-width: 1024px) {
      height: 35vw;
      display: flex;
    }

    background: rgba(22, 27, 33, 0.7);
    opacity: 0;
    transition: 0.3s;
    padding: 20px 40px;
    box-sizing: border-box;
    h2 {
      font-weight: 400;
      font-size: 32px;
      color: #ffffff;
      line-height: 1.2;
      letter-spacing: -0.02em;
      @media only screen and (min-width: 1024px) {
        font-size: 45px;
      }
    }
    .desc {
      font-size: 16px;
      color: rgba(255, 255, 255, 0.7);
      font-weight: 400;
      line-height: 1.6;
      letter-spacing: 0;
      text-align: center;
      @media only screen and (min-width: 1024px) {
        font-size: 20px;
      }
    }
  }
  .content:hover {
    opacity: 1;
  }

  .mobile_title {
    padding-bottom: 20px;
    font-weight: 400;
    color: #2a2f36;
    line-height: 1.2;
    letter-spacing: -0.02em;
    @media only screen and (min-width: 1024px) {
      display: none;
    }
  }
  .mobile_desc {
    font-weight: 400;
    color: #6c7a89;
    border-bottom: 1px solid #2a2f36;
    padding: 20px 0;
    @media only screen and (min-width: 1024px) {
      display: none;
    }
  }
`;
function ProjectComponent({ link, src, title, description }) {
  return (
    <ProjectComponentCss>
      <Link className="link" to={link}>
        <h2 className="mobile_title">{title}</h2>
        <div className="background" style={{ backgroundImage: `url(${src})` }}>
          <div className="content">
            <h2>{title}</h2>
            <p className="desc">{description}</p>
          </div>
        </div>
        <p className="mobile_desc">{description}</p>
      </Link>
    </ProjectComponentCss>
  );
}

export default ProjectComponent;
