import React, { useEffect, useState } from "react";
import styled from "styled-components";

import { useLocation, useNavigate } from "react-router-dom";
import { TfiAngleLeft } from "react-icons/tfi";
import Footer from "./Component/Footer";
import locationBlackIcon from "./Img/MainEventComponent/locationBlack.svg";
import dateBlackIcon from "./Img/MainEventComponent/dateBlack.svg";
import ticketIcon from "./Img/ReserveTicket/ticket.svg";
import PopUp from "./Component/PopUp";
import dummyData1 from "./Img/Main/dummydata1.svg";
const ReserveTicketDetailCSS = styled.div`
  position: relative;
  width: 100vw;
  height: 82vh;
  @media only screen and (min-width: 1024px) {
    height: 100vh;
  }
  max-width: 450px;
  overflow: auto;
  .header {
    padding: 10px 0;
    width: 100%;
    display: flex;
    align-items: center;
    .title {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 80%;
    }
    .exit {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 10%;
      font-size: 20px;
      cursor: pointer;
    }
  }
  .borderLine {
    margin: 0 20px;
    border-bottom: 1.5px solid #e6e6e6;
  }
  .layout {
    display: flex;
    cursor: pointer;
    overflow: auto;
  }
  .img {
    background-image: url("${(props) => props.img}");
    background-position: center;
    background-size: cover;
    height: 155px;
    width: 111px;
    margin: 10px 20px 10px 20px;
  }
  .content {
    margin: 10px 20px 10px 0px;
    width: 260px;
    display: flex;
    flex-direction: column;
  }
  .category {
    font-size: 13px;
    font-weight: 600;
    margin: 5px 0 0 0;
  }
  .title {
    width: 200px;
    white-space: nowrap;
    overflow: hidden;
    color: #080708;
    text-overflow: ellipsis;
    font-size: 16px;
    font-weight: 600;
    margin: 5px 0 10px 0;
  }
  .container {
    display: flex;
    align-items: center;
    margin-top: 5px;
  }
  img {
    margin-right: 4px;
  }
  .text {
    color: #080708;
    font-size: 13px;
    font-weight: 400;
    margin: 0;
  }
  .text2 {
    color: #080708;
    font-size: 13px;
    font-weight: 500;
    margin: 0;
  }
  .button {
    display: flex;
    gap: 8px;
    margin-top: auto;
  }
  .button1 {
    width: 110px;
    height: 25px;
    font-size: 13px;
    color: #981c26;
    background-color: white;
    border-radius: 0;
    border: 1px solid black;
    cursor: pointer;
  }
  .button2 {
    width: 110px;
    height: 25px;
    font-size: 13px;
    color: white;
    background-color: #981c26;
    border-radius: 0;
    border: 1px solid #981c26;
    cursor: pointer;
  }
  .description {
    margin: 0 20px;
  }
  .subtitle {
    font-size: 16px;
    font-weight: 600;
  }
  .subInfo {
    display: flex;
  }
  .infoTitle {
    display: flex;
    flex-direction: column;
    font-size: 13px;
    margin-right: 35px;
    p {
      margin: 7px 0;
    }
  }
  .info {
    display: flex;
    flex-direction: column;
    font-size: 13px;
    p {
      margin: 7px 0;
    }
  }
  .ticketInfo {
    display: flex;
    font-size: 13px;
    justify-content: space-between;
    p {
      margin: 7px 0;
      white-space: nowrap;
    }
  }
  .price {
    width: 100%;
  }
  .priceDetail {
    display: flex;
    justify-content: space-between;
  }

  .totalPrice {
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-size: 13px;
  }
  .ticketBold,
  .priceBold {
    font-weight: 600;
  }
`;

function ReserveTicketDetail() {
  const navigate = useNavigate();
  const [data, setData] = useState({
    title: "뮤지컬 〈브로드웨이 42번가〉",
    category: "공연",
    location: "서울특별시 송파구 잠실동 40-1",
    place_name: "샤롯데씨어터",
    location_x: 37.5112866236555,
    location_y: 127.097939034042,
    homepage: "https://tickets.interpark.com/goods/25007451",
    description: `국내 초연 21주년, 브로드웨이 스테디셀러 뮤지컬
    브로드웨이 5,000회 이상 정기공연 기록!
    1996년 국내 초연 이후 21년 동안 써내려간 흥행불패의 신화
    2016년 20주년 공연의 성공적인 피날레에 힘입어
    격이 다른 뮤지컬의 진화판 ‘21년산’으로 되돌아오다.

    경쾌하고 짜릿한 쇼 뮤지컬의 진수, 더욱 완벽해진 무대로 찾아오다!

    20주년 기념공연에서 새롭게 선보인 장면들의 안무, 세트, 조명을 보완해
    압도적인 입체감과 역대 최고 레벨의 탭댄스를 선보인다.
    올 여름 누구나 즐길 수 있는 짜릿한 퍼포먼스와 차원이 다른 고품격 무대가 펼쳐진다.

    BEST CASTING MATCH, 믿고 보는 배우들의 환상적인 조합
    카리스마 넘치는 ‘외강내유’ 형 줄리안 마쉬, 김석훈!
    시크하면서도 반전 있는 ‘외유내강’형 줄리안마쉬, 이종혁!
    21년 만에 뭉친 초연콤비, 최정원, 전수경!
    새롭게 합류한 NEW CAST, 배해선, 오소연!
    환상호흡의 최정예 멤버, 전예지, 에녹, 전재홍!
    새롭고 품격 있는 캐스트로 차원이 다른 21주년 무대를 선보인다.`,
    start_date: "2025-07-10T00:00:00",
    end_date: "2025-09-14T00:00:00",
    open: "오픈 시간",
    close: "휴관 일",
    charge: 1,
    view: 10, //조회수
    wraning: 0, // 신고 횟수
    hashtag_list: ["#신나는", "#탭댄스"], // 해시태그
    event_review_list: [], //이벤트 리뷰 응답형식 참고
    fee: [
      { target: "VIP", price: 130000 },
      { target: "OP석", price: 110000 },
      { target: "R석", price: 110000 },
      { target: "S석", price: 80000 },
      { target: "A선", price: 60000 },
    ],
  });

  const [img, setImg] = useState(dummyData1);
  const [ticketInfo, setTicketInfo] = useState({
    ticket_number: "T2351571590",
    name: "홍길동",
    state: "예매완료",
    date: "2025-07-15T19:30:00",
    take_place: "현장에서 티켓으로 교환",
    ticket_num: [
      { target: "VIP", count: 2, price: 130000 },
      { target: "OP석", count: 2, price: 110000 },
    ],
    price: 240000,
    create_at: "2025-07-10T20:22:00",
  });

  const [isPopupOpen, setPopupOpen] = useState(false);
  const togglePopup = () => {
    setPopupOpen(!isPopupOpen);
  };
  const handleCancelClick = (e) => {
    e.preventDefault();
    e.stopPropagation();
    togglePopup();
  };
  const handleClose = () => {
    setPopupOpen(false);
  };
  const color = {
    전시회: "#1593FF",
    공연: "#F3757C",
    축제: "#EFA116",
    "원데이 클래스": "#981C26",
  };
  const state = {
    예매완료: "#981C26",
    예매취소: "#1593FF",
  };
  useEffect(() => {
    const ticket_info_copy = { ...ticketInfo };
    const date = ticketInfo.date.split("T");
    const date1 = date[1].split(":");
    const create_at = ticketInfo.create_at.split("T");
    const create_at1 = create_at[1].split(":");
    ticket_info_copy.date = `${date[0]} ${date1[0]}:${date1[1]}`;
    ticket_info_copy.create_at = `${create_at[0]} ${create_at1[0]}:${create_at1[1]}`;
    setTicketInfo(ticket_info_copy);
  }, []);
  return (
    <ReserveTicketDetailCSS img={img}>
      {isPopupOpen && <PopUp type={1} handleClose={handleClose} />}
      <div className="header">
        <p
          className="exit"
          onClick={() => {
            navigate(-1);
          }}
        >
          <TfiAngleLeft />
        </p>
        <p className="title">예매상세내역</p>
      </div>
      <div className="layout">
        <div className="img"></div>
        <div className="content">
          <p className="category" style={{ color: color[data.category] }}>
            {data.category}
          </p>
          <p className="title">{data.title}</p>
          <div className="container">
            <img src={locationBlackIcon} alt="location" />
            <p className="text">
              {data.location !== undefined &&
                data.location.split(" ")[0] +
                  " · " +
                  data.location.split(" ")[1]}
            </p>
          </div>
          <div className="container">
            <img src={dateBlackIcon} alt="date" />
            <p className="text">{}</p>
          </div>

          {/*TODO: 예매취소한 경우에 따라서 다르게 구현*/}
          <div className="container">
            <img src={ticketIcon} alt="ticket" />
            <p className="text2">T2351571590 ·&nbsp;</p>
            <p className="text2" style={{ color: state["예매완료"] }}>
              예매완료
            </p>
            {/*<p className="text2" style={{ color: state["예매취소"] }}>예매취소</p>*/}
          </div>

          {/*TODO: 관람일시 지난 경우(현재 시각과 관람 일시 비교), 예매취소한 경우 고려하여 구현*/}
          <div className="container button">
            <button
              className="button1"
              type="button"
              onClick={handleCancelClick}
            >
              예매취소
            </button>
            <button
              className="button2"
              type="button"
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                navigate(`/nearby//event/review-create`);
              }}
            >
              관람후기 작성
            </button>
            {/*<button className="button1" type="button" onClick={undefined}>문의하기</button>*/}
          </div>
        </div>
      </div>
      <p className="borderLine"></p>
      <div className="description">
        <p className="subtitle">예매정보</p>
        <div className="subInfo">
          <div className="infoTitle">
            <p>관람일시</p>
            <p>예매일</p>
            <p>예매번호</p>
            <p>예매자명</p>
            <p>예매상태</p>
            <p>수령방법</p>
          </div>
          <div className="info">
            <p>{ticketInfo.date}</p>
            <p>{ticketInfo.create_at}</p>
            <p className="ticketBold">{ticketInfo.ticket_number}</p>
            <p>{ticketInfo.name}</p>
            <p>{ticketInfo.state}</p>
            <p>{ticketInfo.take_place}</p>
          </div>
        </div>
        <p className="subtitle">결제정보</p>
        <div>
          <div className="ticketInfo">
            <div className="infoTitle">
              <p>티켓정보</p>
            </div>
            <div className="price">
              {ticketInfo.ticket_num.map((e, idx) => {
                return (
                  <div className="priceDetail">
                    <p>{`${e.target} ${e.count} 매`}</p>
                    <p>{e.price}</p>
                  </div>
                );
              })}
            </div>
          </div>
          <div className="totalPrice">
            <p>결제금액</p>
            <p className="priceBold">{ticketInfo.price}</p>
          </div>
        </div>
      </div>
      <div style={{ height: "20vh", width: "100%" }}></div>
      <Footer mode={3} />
    </ReserveTicketDetailCSS>
  );
}
export default ReserveTicketDetail;
