import { Link } from "react-router-dom";
import styled from "styled-components";

const TagComponentCss = styled.div`
  margin: 5px 0;
  .link {
    display: flex;
    text-decoration: none;
    background: #ffffff;
    color: #2a2f36;
    font-size: 26px;
    align-items: center;
    justify-content: center;
    width: calc(calc(calc(100vw - 40px) / 3) - 4px);
    height: 80px;
    border: 1px solid #2a2f36;
    box-sizing: border-box;
    border-radius: 8px;
    @media only screen and (min-width: 1024px) {
      width: calc(calc(calc(70vw - 120px) / 3) - 2px);
      font-size: 26px;
    }
    @media only screen and (min-width: 1600px) {
      width: calc(calc(calc(75vw - 120px) / 4) - 3px);
    }
  }
`;
function TagComponent({ tag }) {
  return (
    <TagComponentCss>
      <Link to={`/tags/${tag}`} className="link">
        # {tag}
      </Link>
    </TagComponentCss>
  );
}

export default TagComponent;
