import styled from "styled-components";
import ProjectComponent from "../../components/projectComponent";
import nearbyCover from "../../assets/img/nearby_cover.svg";
import howai from "../../assets/img/howai.jpg";
const ProjectsCss = styled.div`
  width: 100%;
  height: 82vh;
  overflow: auto;
  padding: 20px;
  box-sizing: border-box;
  @media only screen and (min-width: 1024px) {
    height: 100vh;
    padding: 60px;
  }
  .intro {
    font-weight: 500;
    font-style: normal;
    line-height: 1;
    color: #2a2f36;
    font-size: 50px;
  }
  .list {
    margin-top: 60px;
    padding-bottom: 20px;
  }
`;

function Projects() {
  const data = [
    {
      link: "/nearby",
      src: nearbyCover,
      title: "nearby",
      description: "위치기반 티켓사이트",
    },
    {
      link: "https://github.com/how-about-idea",
      src: howai,
      title: "How About Idea(HowAI)",
      description: "TextRank 알고리즘 및 인공지능을 활용한 브레인스토밍",
    },
  ];
  return (
    <ProjectsCss>
      <h1 className="intro">Projects</h1>
      <div className="list">
        {data.map((e, idx) => {
          return (
            <ProjectComponent
              key={idx}
              link={e.link}
              src={e.src}
              title={e.title}
              description={e.description}
            />
          );
        })}
      </div>
    </ProjectsCss>
  );
}

export default Projects;
