import { useRef, useState, useEffect } from "react";

export default function useLazyBackground(arg1, arg2, arg3 = {}) {
  const internalRef = useRef(null);
  const [imgSrc, setImgSrc] = useState("");

  //모드 판별
  const cssBackgroundMode =
    typeof arg1 === "object" && arg1 !== null && "current" in arg1;

  const ref = cssBackgroundMode ? arg1 : internalRef;
  const realUrl = cssBackgroundMode ? arg2 : arg1;
  const options = cssBackgroundMode ? arg3 : arg2 ?? {};

  useEffect(() => {
    if (!ref.current) return;

    if (cssBackgroundMode)
      ref.current.style.background = options.placeholder ?? "#eee";

    //테스트용
    ref.current.style.opacity = "0";
    ref.current.style.transition = "opacity s ease";

    //기준 쿼리 계산
    const root =
      options.root ??
      (() => {
        let el = ref.current.parentElement;
        while (el && el !== document.body) {
          if (/(auto|scroll)/.test(getComputedStyle(el).overflowY)) return el;
          el = el.parentElement;
        }
        return null;
      })();

    const io = new IntersectionObserver(
      ([entry], obs) => {
        if (entry.isIntersecting) {
          if (cssBackgroundMode) {
            ref.current.style.backgroundImage = `url(${realUrl})`;
            ref.current.style.backgroundSize = "cover";
            ref.current.style.backgroundPosition = "center";
          } else {
            setImgSrc(realUrl);
          }

          //테스트용 코드
          requestAnimationFrame(() => {
            if (ref.current) ref.current.style.opacity = "1";
          });

          console.log("lazy loaded:", realUrl);

          obs.unobserve(entry.target);
        }
      },
      {
        root,
        rootMargin: options.rootMargin ?? "300px",
        threshold: options.threshold ?? 0,
      }
    );

    io.observe(ref.current);
    return () => io.disconnect();
  }, [realUrl, options, cssBackgroundMode, ref]);

  return cssBackgroundMode ? undefined : [ref, imgSrc];
}
