import { persist } from "zustand/middleware";
import { create } from "zustand";
import fm from "front-matter";
import { mdLink } from "../store/mdLink";
function loadDevServerPost() {
  const fileInfos = mdLink.map((key) => ({
    filename: key,
    url: process.env.PUBLIC_URL + "/posts/md/" + key, // Webpack이 변환한 static URL
  }));

  return Promise.all(
    fileInfos.map(async ({ filename, url }) => {
      const res = await fetch(url);
      const text = await res.text();
      const parsed = fm(text);
      const img = `${process.env.PUBLIC_URL}/posts/assets/${
        filename.split(".md")[0]
      }/${parsed.attributes.src}`;

      return {
        filename,
        ...parsed.attributes,
        src: img,
        date: parsed.attributes.date.toDateString(),
        body: parsed.body,
      };
    })
  );
}

function loadGithubServerPost() {
  const fileInfos = mdLink.map((key) => ({
    filename: key,
    url:
      "https://raw.githubusercontent.com/honggibeom/honggibeom.github.io/gh-pages/posts/md/" +
      key,
  }));
  return Promise.all(
    fileInfos.map(async ({ filename, url }) => {
      const res = await fetch(url);
      const text = await res.text();
      const parsed = fm(text);
      const img = `https://github.com/honggibeom/honggibeom.github.io/raw/gh-pages/posts/assets/${
        filename.split(".md")[0]
      }/${parsed.attributes.src}`;

      return {
        filename,
        ...parsed.attributes,
        src: img,
        date: parsed.attributes.date.toDateString(),
        body: parsed.body,
      };
    })
  );
}

function loadPost() {
  if (process.env.NODE_ENV === "development") return loadDevServerPost();
  else return loadGithubServerPost();
}

export const usePostsStore = create(
  persist((set) => ({
    posts: [],
    tags: {},
    name: {},
    setPosts: async () => {
      const res = await loadPost();
      const tags_copy = {};
      const name_copy = {};
      for (let i = 0; i < res.length; i++) {
        name_copy[res[i].title] = res[i];
        for (const tag of res[i].tags) {
          if (tags_copy[tag] === undefined) {
            tags_copy[tag] = [res[i]];
          } else {
            tags_copy[tag].push(res[i]);
          }
        }
      }

      set({
        posts: res,
        tags: tags_copy,
        name: name_copy,
      });
    },
  }))
);
