import { useEffect, useReducer, useRef, useState } from "react";
import styled from "styled-components";
import { usePostsStore } from "../../store/postsStore";
import TagComponent from "../../components/tagComponent";
import { IoSearchOutline } from "react-icons/io5";
import useDebounce from "../../hooks/useDebounce";
const TagsCss = styled.div`
  width: 100%;
  height: 82vh;
  overflow: auto;
  padding: 20px;
  box-sizing: border-box;
  @media only screen and (min-width: 1024px) {
    height: 100vh;
    padding: 60px;
  }
  .intro {
    font-weight: 500;
    font-style: normal;
    line-height: 1;
    color: #2a2f36;
    font-size: 50px;
  }

  .list {
    display: flex;
    flex-wrap: wrap;
    padding-bottom: 20px;
    gap: 6px;
    @media only screen and (min-width: 1024px) {
      gap: 3px;
    }
    @media only screen and (min-width: 1600px) {
      gap: 4px;
    }
  }

  .searchBar {
    display: flex;
    width: 100%;
    margin: 20px 0;
    padding: 10px 20px;
    box-sizing: border-box;
    border-radius: 12px;
    align-items: center;
    justify-content: space-between;
    border: 1px solid #000000;
    @media only screen and (min-width: 1024px) {
      padding: 12px 20px;
    }
    input {
      border: 0;
      width: 95%;
      font-size: 16px;
      @media only screen and (min-width: 1024px) {
        font-size: 20px;
      }
    }
    input:focus {
      outline: none;
    }
    .icon {
      font-size: 24px;
    }
  }
`;

function Tags() {
  const tags = usePostsStore((state) => state.tags);
  const [result, setResult] = useState(Object.keys(tags));
  const [text, setText] = useState("");
  const debouncedValue = useDebounce(text, 500);
  useEffect(() => {
    if (debouncedValue.length === 0) setResult(Object.keys(tags));
    else {
      const lowCase = debouncedValue.toLowerCase();
      let result_copy = [];
      for (const tag of Object.keys(tags)) {
        if (tag.toLowerCase().includes(lowCase)) result_copy.push(tag);
      }
      setResult(result_copy);
    }
  }, [debouncedValue]);

  return (
    <TagsCss>
      <h1 className="intro">Tags</h1>
      <label className="searchBar">
        <input
          type="text"
          onChange={(e) => {
            setText(e.target.value);
          }}
        />
        <IoSearchOutline className="icon" />
      </label>
      <div className="list">
        {result.map((e, idx) => {
          return <TagComponent key={idx} tag={e} />;
        })}
      </div>
    </TagsCss>
  );
}

export default Tags;
